    final public static function fromJSON(string $json): Document {}

/**
 * <div id="mongodb-bson-document.fromphp" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::fromPHP</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::fromPHP</span> — <span class="dc-title">Construct a new document instance from PHP data</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.fromphp-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">static</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::fromPHP</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$value</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.fromphp-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">value</span> (<span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span>)</dt>    <dd>     <span class="simpara">      A PHP object or array containing the document. When passing an array with      numeric keys, the numeric values are converted to strings and used as      document keys.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.fromphp-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span> instance.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.fromphp-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.fromphp-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::fromBSON()} - Construct a new document instance from a BSON string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::fromJSON()} - Construct a new document instance from a JSON string</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public static function fromPHP(array|object $value): Document {}

/**
 * <div id="mongodb-bson-document.get" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::get</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::get</span> — <span class="dc-title">Returns the value of a key in the document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.get-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::get</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.get-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">key</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      The key to retrieve from the document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.get-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the value associated with the given key. If the key is not present in   the document, an exception is thrown.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When encountering a value encoded as 64-bit integer in the BSON document,    the return value of this method will be a    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> instance.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.get-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the key is not present in the document.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.get-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::has()} - Returns whether a key is present in the document</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function get(string $key): mixed {}

/**
 * <div id="mongodb-bson-document.getiterator" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::getIterator</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::getIterator</span> — <span class="dc-title">Returns an iterator for the BSON document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.getiterator-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::getIterator</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-iterator.php" class="type MongoDB\BSON\Iterator" style="color:#EAB766">MongoDB\BSON\Iterator</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.getiterator-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.getiterator-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-iterator.php" class="classname">MongoDB\BSON\Iterator</a></span> instance that can be   used to iterate over all keys in the document.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.getiterator-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-unexpectedvalueexception.php" class="classname">MongoDB\Driver\Exception\UnexpectedValueException</a></span> if the BSON iterator could not be initialized.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.getiterator-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function getIterator(): Iterator {}

/**
 * <div id="mongodb-bson-document.has" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::has</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::has</span> — <span class="dc-title">Returns whether a key is present in the document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.has-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::has</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.has-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">key</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      The key to look for in the document.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.has-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if the key is present in the document and <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> otherwise.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.has-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.has-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::get()} - Returns the value of a key in the document</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
