/**
 * <div id="mongodb-bson-document.tophp" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::toPHP</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::toPHP</span> — <span class="dc-title">Returns the PHP representation of the BSON document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.tophp-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::toPHP</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$typeMap</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span></div>  <p class="simpara">   Unserializes the BSON document to its PHP representation. The   <span class="parameter" style="color:#3A95FF">typeMap</span> parameter may be used to control the PHP types   used for converting BSON arrays and documents (both root and embedded).  </p>     <div class="warning"><strong class="warning">警告</strong>    <p class="simpara">     BSON documents can technically contain duplicate keys because documents are     stored as a list of key-value pairs; however, applications should refrain     from generating documents with duplicate keys as server and driver behavior     may be undefined. Since PHP objects and arrays cannot have duplicate keys,     data could also be lost when decoding a BSON document with duplicate keys.    </p>   </div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.tophp-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">typeMap</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>)</dt>    <dd>     <span class="simpara">      <a href="https://php.net/manual/zh/mongodb.persistence.php#mongodb.persistence.typemaps" class="link">Type map configuration</a>.     </span>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.tophp-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The decoded PHP value.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When encountering a value encoded as 64-bit integer in the BSON document,    the return value of this method will be a    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> instance.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.tophp-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>    Throws    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if    a class in the type map cannot be instantiated or does not implement    <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-unserializable.php" class="interfacename">MongoDB\BSON\Unserializable</a></span>.   </li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.tophp-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\BSON\toPHP()} - Returns the PHP representation of a BSON value</span></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function toPHP(?array $typeMap = null): array|object {}

/**
 * <div id="mongodb-bson-document.tocanonicalextendedjson" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::toCanonicalExtendedJSON</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::toCanonicalExtendedJSON</span> — <span class="dc-title">Returns the Canonical Extended JSON representation of the BSON document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.tocanonicalextendedjson-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::toCanonicalExtendedJSON</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Converts the BSON document to its   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;Canonical Extended JSON</a>   representation. The canonical format prefers type fidelity at the expense of   concise output and is most suited for producing output that can be converted   back to BSON without any loss of type information (e.g. numeric types will   remain differentiated).  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.tocanonicalextendedjson-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.tocanonicalextendedjson-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a string containing the   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#canonical-extended-json-example" class="link external">»&nbsp;Canonical Extended JSON</a>   representation of the BSON document.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-document.tocanonicalextendedjson-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::toCanonicalExtendedJSON()</strong></span> example</strong></p>   <div class="example-contents">    <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$documents </span><span style="color: #007700">= [<br>    [ </span><span style="color: #DD0000">'null' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">null </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'boolean' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'string' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'foo' </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'int32' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">123 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'int64' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4294967295 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'double' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1.0 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'nan' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">NAN </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'pos_inf' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">INF </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'neg_inf' </span><span style="color: #007700">=&gt; -</span><span style="color: #9876AA">INF </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'array' </span><span style="color: #007700">=&gt; [ </span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #DD0000">'bar' </span><span style="color: #007700">]],<br>    [ </span><span style="color: #DD0000">'document' </span><span style="color: #007700">=&gt; [ </span><span style="color: #DD0000">'foo' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'bar' </span><span style="color: #007700">]],<br>    [ </span><span style="color: #DD0000">'oid' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'56315a7c6118fd1b920270b1'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'dec128' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #DD0000">'1234.5678'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'binary' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">(</span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_GENERIC</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'date' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\UTCDateTime</span><span style="color: #007700">(</span><span style="color: #9876AA">1445990400000</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'timestamp' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Timestamp</span><span style="color: #007700">(</span><span style="color: #9876AA">1234</span><span style="color: #007700">, </span><span style="color: #9876AA">5678</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'regex' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Regex</span><span style="color: #007700">(</span><span style="color: #DD0000">'pattern'</span><span style="color: #007700">, </span><span style="color: #DD0000">'i'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'code' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Javascript</span><span style="color: #007700">(</span><span style="color: #DD0000">'function() { return 1; }'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'code_ws' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Javascript</span><span style="color: #007700">(</span><span style="color: #DD0000">'function() { return a; }'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'a' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]) ],<br>    [ </span><span style="color: #DD0000">'minkey' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\MinKey </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'maxkey' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\MaxKey </span><span style="color: #007700">],<br>];<br><br>foreach (</span><span style="color: #9876AA">\$documents </span><span style="color: #007700">as </span><span style="color: #9876AA">\$document</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">\$bson </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$document</span><span style="color: #007700">);<br>    echo </span><span style="color: #9876AA">\$bson</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toCanonicalExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;">    <div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"null"&nbsp;:&nbsp;null&nbsp;}<br>{&nbsp;"boolean"&nbsp;:&nbsp;true&nbsp;}<br>{&nbsp;"string"&nbsp;:&nbsp;"foo"&nbsp;}<br>{&nbsp;"int32"&nbsp;:&nbsp;{&nbsp;"\$numberInt"&nbsp;:&nbsp;"123"&nbsp;}&nbsp;}<br>{&nbsp;"int64"&nbsp;:&nbsp;{&nbsp;"\$numberLong"&nbsp;:&nbsp;"4294967295"}&nbsp;}<br>{&nbsp;"double"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"1.0"&nbsp;}&nbsp;}<br>{&nbsp;"nan"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"NaN"&nbsp;}&nbsp;}<br>{&nbsp;"pos_inf"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"Infinity"&nbsp;}&nbsp;}<br>{&nbsp;"neg_inf"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"-Infinity"&nbsp;}&nbsp;}<br>{&nbsp;"array"&nbsp;:&nbsp;[&nbsp;"foo",&nbsp;"bar"&nbsp;]&nbsp;}<br>{&nbsp;"document"&nbsp;:&nbsp;{&nbsp;"foo"&nbsp;:&nbsp;"bar"&nbsp;}&nbsp;}<br>{&nbsp;"oid"&nbsp;:&nbsp;{&nbsp;"\$oid"&nbsp;:&nbsp;"56315a7c6118fd1b920270b1"&nbsp;}&nbsp;}<br>{&nbsp;"dec128"&nbsp;:&nbsp;{&nbsp;"\$numberDecimal"&nbsp;:&nbsp;"1234.5678"&nbsp;}&nbsp;}<br>{&nbsp;"binary"&nbsp;:&nbsp;{&nbsp;"\$binary"&nbsp;:&nbsp;{&nbsp;"base64":&nbsp;"Zm9v",&nbsp;"subType"&nbsp;:&nbsp;"00"&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"date"&nbsp;:&nbsp;{&nbsp;"\$date"&nbsp;:&nbsp;{&nbsp;"\$numberLong"&nbsp;:&nbsp;"1445990400000"&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"timestamp"&nbsp;:&nbsp;{&nbsp;"\$timestamp"&nbsp;:&nbsp;{&nbsp;"t"&nbsp;:&nbsp;5678,&nbsp;"i"&nbsp;:&nbsp;1234&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"regex"&nbsp;:&nbsp;{&nbsp;"\$regularExpression"&nbsp;:&nbsp;{&nbsp;"pattern"&nbsp;:&nbsp;"pattern",&nbsp;"options"&nbsp;:&nbsp;"i"&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"code"&nbsp;:&nbsp;{&nbsp;"\$code"&nbsp;:&nbsp;"function()&nbsp;{&nbsp;return&nbsp;1;&nbsp;}"&nbsp;}&nbsp;}<br>{&nbsp;"code_ws"&nbsp;:&nbsp;{&nbsp;"\$code"&nbsp;:&nbsp;"function()&nbsp;{&nbsp;return&nbsp;a;&nbsp;}",&nbsp;"\$scope"&nbsp;:&nbsp;{&nbsp;"a"&nbsp;:&nbsp;{&nbsp;"\$numberInt"&nbsp;:&nbsp;"1"&nbsp;}&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"minkey"&nbsp;:&nbsp;{&nbsp;"\$minKey"&nbsp;:&nbsp;1&nbsp;}&nbsp;}<br>{&nbsp;"maxkey"&nbsp;:&nbsp;{&nbsp;"\$maxKey"&nbsp;:&nbsp;1&nbsp;}&nbsp;}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.tocanonicalextendedjson-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::fromJSON()} - Construct a new document instance from a JSON string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of the BSON document</span></li>   <li><span class="function">{@link MongoDB\BSON\toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of a BSON value</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md" class="link external">»&nbsp;Extended JSON Specification</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function toCanonicalExtendedJSON(): string {}

/**
 * <div id="mongodb-bson-document.torelaxedextendedjson" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::toRelaxedExtendedJSON</h1>  <p class="verinfo">(mongodb &gt;=1.16.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::toRelaxedExtendedJSON</span> — <span class="dc-title">Returns the Relaxed Extended JSON representation of the BSON document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.torelaxedextendedjson-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::toRelaxedExtendedJSON</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Converts the BSON document to its   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#relaxed-extended-json-example" class="link external">»&nbsp;Relaxed Extended JSON</a>   representation. The relaxed format prefers use of JSON type primitives at the   expense of type fidelity and is most suited for producing output that can be   easily consumed by web APIs and humans.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.torelaxedextendedjson-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.torelaxedextendedjson-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns a string containing the   <a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md#relaxed-extended-json-example" class="link external">»&nbsp;Relaxed Extended JSON</a>   representation of the BSON document.  </p> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-document.torelaxedextendedjson-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::toRelaxedExtendedJSON()</strong></span> example</strong></p>   <div class="example-contents">    <div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$documents </span><span style="color: #007700">= [<br>    [ </span><span style="color: #DD0000">'null' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">null </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'boolean' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">true </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'string' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'foo' </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'int32' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">123 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'int64' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4294967295 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'double' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1.0 </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'nan' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">NAN </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'pos_inf' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">INF </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'neg_inf' </span><span style="color: #007700">=&gt; -</span><span style="color: #9876AA">INF </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'array' </span><span style="color: #007700">=&gt; [ </span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #DD0000">'bar' </span><span style="color: #007700">]],<br>    [ </span><span style="color: #DD0000">'document' </span><span style="color: #007700">=&gt; [ </span><span style="color: #DD0000">'foo' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'bar' </span><span style="color: #007700">]],<br>    [ </span><span style="color: #DD0000">'oid' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">(</span><span style="color: #DD0000">'56315a7c6118fd1b920270b1'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'dec128' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Decimal128</span><span style="color: #007700">(</span><span style="color: #DD0000">'1234.5678'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'binary' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">(</span><span style="color: #DD0000">'foo'</span><span style="color: #007700">, </span><span style="color: #9876AA">MongoDB\BSON\Binary</span><span style="color: #007700">::</span><span style="color: #9876AA">TYPE_GENERIC</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'date' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\UTCDateTime</span><span style="color: #007700">(</span><span style="color: #9876AA">1445990400000</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'timestamp' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Timestamp</span><span style="color: #007700">(</span><span style="color: #9876AA">1234</span><span style="color: #007700">, </span><span style="color: #9876AA">5678</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'regex' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Regex</span><span style="color: #007700">(</span><span style="color: #DD0000">'pattern'</span><span style="color: #007700">, </span><span style="color: #DD0000">'i'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'code' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Javascript</span><span style="color: #007700">(</span><span style="color: #DD0000">'function() { return 1; }'</span><span style="color: #007700">) ],<br>    [ </span><span style="color: #DD0000">'code_ws' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\Javascript</span><span style="color: #007700">(</span><span style="color: #DD0000">'function() { return a; }'</span><span style="color: #007700">, [</span><span style="color: #DD0000">'a' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">]) ],<br>    [ </span><span style="color: #DD0000">'minkey' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\MinKey </span><span style="color: #007700">],<br>    [ </span><span style="color: #DD0000">'maxkey' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MongoDB\BSON\MaxKey </span><span style="color: #007700">],<br>];<br><br>foreach (</span><span style="color: #9876AA">\$documents </span><span style="color: #007700">as </span><span style="color: #9876AA">\$document</span><span style="color: #007700">) {<br>    </span><span style="color: #9876AA">\$bson </span><span style="color: #007700">= </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$document</span><span style="color: #007700">);<br>    echo </span><span style="color: #9876AA">\$bson</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;">    <div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"null"&nbsp;:&nbsp;null&nbsp;}<br>{&nbsp;"boolean"&nbsp;:&nbsp;true&nbsp;}<br>{&nbsp;"string"&nbsp;:&nbsp;"foo"&nbsp;}<br>{&nbsp;"int32"&nbsp;:&nbsp;123&nbsp;}<br>{&nbsp;"int64"&nbsp;:&nbsp;4294967295&nbsp;}<br>{&nbsp;"double"&nbsp;:&nbsp;1.0&nbsp;}<br>{&nbsp;"nan"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"NaN"&nbsp;}&nbsp;}<br>{&nbsp;"pos_inf"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"Infinity"&nbsp;}&nbsp;}<br>{&nbsp;"neg_inf"&nbsp;:&nbsp;{&nbsp;"\$numberDouble"&nbsp;:&nbsp;"-Infinity"&nbsp;}&nbsp;}<br>{&nbsp;"array"&nbsp;:&nbsp;[&nbsp;"foo",&nbsp;"bar"&nbsp;]&nbsp;}<br>{&nbsp;"document"&nbsp;:&nbsp;{&nbsp;"foo"&nbsp;:&nbsp;"bar"&nbsp;}&nbsp;}<br>{&nbsp;"oid"&nbsp;:&nbsp;{&nbsp;"\$oid"&nbsp;:&nbsp;"56315a7c6118fd1b920270b1"&nbsp;}&nbsp;}<br>{&nbsp;"dec128"&nbsp;:&nbsp;{&nbsp;"\$numberDecimal"&nbsp;:&nbsp;"1234.5678"&nbsp;}&nbsp;}<br>{&nbsp;"binary"&nbsp;:&nbsp;{&nbsp;"\$binary"&nbsp;:&nbsp;{&nbsp;"base64":&nbsp;"Zm9v",&nbsp;"subType"&nbsp;:&nbsp;"00"&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"date"&nbsp;:&nbsp;{&nbsp;"\$date"&nbsp;:&nbsp;"2015-10-28T00:00:00Z"&nbsp;}&nbsp;}<br>{&nbsp;"timestamp"&nbsp;:&nbsp;{&nbsp;"\$timestamp"&nbsp;:&nbsp;{&nbsp;"t"&nbsp;:&nbsp;5678,&nbsp;"i"&nbsp;:&nbsp;1234&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"regex"&nbsp;:&nbsp;{&nbsp;"\$regularExpression"&nbsp;:&nbsp;{&nbsp;"pattern"&nbsp;:&nbsp;"pattern",&nbsp;"options"&nbsp;:&nbsp;"i"&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"code"&nbsp;:&nbsp;{&nbsp;"\$code"&nbsp;:&nbsp;"function()&nbsp;{&nbsp;return&nbsp;1;&nbsp;}"&nbsp;}&nbsp;}<br>{&nbsp;"code_ws"&nbsp;:&nbsp;{&nbsp;"\$code"&nbsp;:&nbsp;"function()&nbsp;{&nbsp;return&nbsp;a;&nbsp;}",&nbsp;"\$scope"&nbsp;:&nbsp;{&nbsp;"a"&nbsp;:&nbsp;1&nbsp;}&nbsp;}&nbsp;}<br>{&nbsp;"minkey"&nbsp;:&nbsp;{&nbsp;"\$minKey"&nbsp;:&nbsp;1&nbsp;}&nbsp;}<br>{&nbsp;"maxkey"&nbsp;:&nbsp;{&nbsp;"\$maxKey"&nbsp;:&nbsp;1&nbsp;}&nbsp;}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.torelaxedextendedjson-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::fromJSON()} - Construct a new document instance from a JSON string</span></li>   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::toCanonicalExtendedJSON()} - Returns the Canonical Extended JSON representation of the BSON document</span></li>   <li><span class="function">{@link MongoDB\BSON\toRelaxedExtendedJSON()} - Returns the Relaxed Extended JSON representation of a BSON value</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/extended-json/extended-json.md" class="link external">»&nbsp;Extended JSON Specification</a></li>   <li><a href="https://www.mongodb.com/docs/manual/reference/bson-types/" class="link external">»&nbsp;BSON Types</a></li>  </ul> </div></div>
 */
    final public function toRelaxedExtendedJSON(): string {}

