/**
 * <div id="mongodb-bson-document.offsetget" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Document::offsetGet</h1>  <p class="verinfo">(mongodb &gt;=1.17.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Document::offsetGet</span> — <span class="dc-title">Returns the value of a key in the document</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-document.offsetget-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Document::offsetGet</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-document.offsetget-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">key</span></dt>     <dd>      <span class="simpara">       The key to retrieve from the document.      </span>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-document.offsetget-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the value associated with the given key. If the key is not present in   the document, an exception is thrown.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When encountering a value encoded as 64-bit integer in the BSON document,    the return value of this method will be a    <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-int64.php" class="classname">MongoDB\BSON\Int64</a></span> instance.   </span>  </p></blockquote> </div> <div class="refsect1 errors" id="refsect1-mongodb-bson-document.offsetget-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> if the key is not present in the document.</li>  </ul> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-document.offsetget-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="methodname" style="color:#CC7832">{@link ArrayAccess::offsetGet()} - 获取一个偏移位置的值</span></li>    <li><span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::get()} - Returns the value of a key in the document</span></li>   </ul>   </div></div>
 */
